export class ProdigyUniformPack
  extends LaterTngBaseUniformPack
  implements IUniformPack
{
  constructor() {
    super(UniformEra.Prodigy);
  }

  getUniformSwatches() {
    return [
      new Swatch(
        BodyType.AverageMale,
        'Average Male',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Base,
              BodyType.AverageMale,
            ),
            BodyType.AverageMale,
            token,
          ),
        'BodyType.averageMale',
      ),
      new Swatch(
        BodyType.AverageFemale,
        'Average Female',
        (token) =>
          UniformCatalog.decorateSwatch(
            this.getUniformAndVariantByBodyType(
              token,
              UniformVariantType.Base,
              BodyType.AverageFemale,
            ),
            BodyType.AverageFemale,
            token,
          ),
        'BodyType.averageFemale',
      ),
    ];
  }

  getUniformVariantSwatches(token: TokenModel) {
    return [
      new Swatch(UniformVariantType.Base, 'Base', (token) =>
        UniformCatalog.decorateSwatch(
          this.getUniformAndVariantByBodyType(
            token,
            UniformVariantType.Base,
            token.bodyType,
          ),
          token.bodyType,
          token,
        ),
      ),
      new Swatch(UniformVariantType.Variant1, 'Protostar Variant', (token) =>
        UniformCatalog.decorateSwatch(
          this.getUniformAndVariantByBodyType(
            token,
            UniformVariantType.Variant1,
            token.bodyType,
          ),
          token.bodyType,
          token,
        ),
      ),
    ];
  }

  getUniformAndVariantBody(token: TokenModel) {
    return this.getUniformAndVariantByBodyType(
      token,
      token.variant,
      token.bodyType,
    );
  }

  getUniformAndVariantByBodyType(
    token: TokenModel,
    variant: UniformVariantType,
    bodyType: BodyType,
  ) {
    let base = '';
    if (bodyType === BodyType.AverageMale) {
      if (isCadetRank(token.rankIndicator)) {
        base = ProdigyUniform.maleCadetBody;
      } else if (variant === UniformVariantType.Variant1) {
        base = ProdigyUniform.maleVariantBody;
      } else {
        base = ProdigyUniform.maleBody;
      }
    } else {
      if (isCadetRank(token.rankIndicator)) {
        base = ProdigyUniform.femaleCadetBody;
      } else if (variant === UniformVariantType.Variant1) {
        base = ProdigyUniform.femaleVariantBody;
      } else {
        base = ProdigyUniform.femaleBody;
      }
    }
    return (
      this.getNeck(
        bodyType,
        token.skinColor,
        token.species,
        UniformEra.DominionWar,
      ) + base
    )
      .replace(DefaultRed, token.divisionColor)
      .replace(SpeciesRestrictions.DEFAULT_SKIN_COLOR_REGEX, token.skinColor);
  }

  getBorderLogo(token: TokenModel): string {
    if (token.variant === UniformVariantType.Variant1) {
      return borderInsignia.variant;
    } else {
      return borderInsignia.standard;
    }
  }

  getRankIndicator(token: TokenModel) {
    let result = super.getRankIndicator(token);
    if (isCadetRank(token.rankIndicator)) {
      if (token.bodyType === BodyType.AverageMale) {
        result = `<g transform="translate(0, -2)">` + result + `</g>`;
      }
    } else if (
      token.variant === UniformVariantType.Base &&
      !isCadetRank(token.rankIndicator)
    ) {
      if (token.bodyType === BodyType.AverageFemale) {
        result = `<g transform="translate(-3, 5)">` + result + `</g>`;
      } else {
        result = `<g transform="translate(-4, 0)">` + result + `</g>`;
      }
    }
    return result;
  }

  getBorderColor(token: TokenModel): string {
    return token.divisionColor;
  }
}
